style.css:
:root,
html,
body {
  /* main accent (buttons, send arrow, highlights) */
  --accent-main-000: #d9ff6b;
  --accent-main-100: #c9f24d;
  --accent-main-200: #b4db3d;
  --accent-main-900: #1f2312;

  /* secondary accents */
  --accent-secondary-000: #e4ff9c;
  --accent-secondary-100: #c9f24d;
  --accent-secondary-200: #b4db3d;
  --accent-secondary-900: #1a1d0f;

  /* the "Pro"/upgrade accent */
  --accent-pro-000: #e4ff9c;
  --accent-pro-100: #c9f24d;
  --accent-pro-200: #b4db3d;
  --accent-pro-900: #1f2312;
}

/* catch stray oranges that aren't variable-driven */
[class*="text-accent"],
a {
  color: #c9f24d !important;
}

svg[class*="text-accent"] path {
  fill: currentColor !important;
}
main {
  background-color: #000000 !important;
}
